( e => {
const { [ 'bg' ]: translations } = {"bg":{"dictionary":{"Copy selected content":"Копиране на избраното съдържание","Paste content":"Поставяне на съдържанието","Paste content as plain text":"Поставяне на съдържанието като обикновен текст"}}};
e[ 'bg' ] ||= { dictionary: {}, getPluralForm: null };
e[ 'bg' ].dictionary = Object.assign( e[ 'bg' ].dictionary, translations.dictionary );
if ( translations.getPluralForm ) {
e[ 'bg' ].getPluralForm = translations.getPluralForm;
}
} )( window.CKEDITOR_TRANSLATIONS ||= {} );
